import json,pathlib
OUT=pathlib.Path(__file__).resolve().parent.parent/'data/jarvis';OUT.mkdir(parents=True,exist_ok=True)
def I(id,domain,keys,ex,text,links=(),follow=(),example=None,more=None,prio=0,ca=None,not_=None,**kw):
    d=dict(id=id,domain=domain,keys=list(keys),examples=list(ex),text=text,links=[{'t':a,'href':b} for a,b in links],follow=list(follow))
    if example:d['example']=example
    if more:d['more']=more
    if prio:d['priority']=prio
    if ca:d['chapterAware']=ca
    if not_:d['not']=not_
    d.update(kw);return d
